import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"정보 및 업데이트","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 컴포넌트 버전 및 프로젝트 정보","slug":"_1-컴포넌트-버전-및-프로젝트-정보","link":"#_1-컴포넌트-버전-및-프로젝트-정보","children":[]},{"level":2,"title":"2. 데이터 디렉토리 및 5단계 백업 롤링 보관","slug":"_2-데이터-디렉토리-및-5단계-백업-롤링-보관","link":"#_2-데이터-디렉토리-및-5단계-백업-롤링-보관","children":[{"level":3,"title":"사용자 데이터 디렉토리 (User Data Directory)","slug":"사용자-데이터-디렉토리-user-data-directory","link":"#사용자-데이터-디렉토리-user-data-directory","children":[]},{"level":3,"title":"머신 데이터 디렉토리 (Machine Data Directory)","slug":"머신-데이터-디렉토리-machine-data-directory","link":"#머신-데이터-디렉토리-machine-data-directory","children":[]},{"level":3,"title":"저장 경로 아키텍처","slug":"저장-경로-아키텍처","link":"#저장-경로-아키텍처","children":[]}]},{"level":2,"title":"3. 업데이트 확인 및 원클릭 업데이트","slug":"_3-업데이트-확인-및-원클릭-업데이트","link":"#_3-업데이트-확인-및-원클릭-업데이트","children":[]},{"level":2,"title":"4. 플러그인 설정 및 설정 백업","slug":"_4-플러그인-설정-및-설정-백업","link":"#_4-플러그인-설정-및-설정-백업","children":[]}],"relativePath":"ko-KR/user-guide/settings/about.md","filePath":"ko-KR/user-guide/settings/about.md","lastUpdated":1791355961000}`),a={name:`ko-KR/user-guide/settings/about.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="정보-및-업데이트" tabindex="-1">정보 및 업데이트 <a class="header-anchor" href="#정보-및-업데이트" aria-label="Permalink to “정보 및 업데이트”">​</a></h1><p>정보 페이지에서는 Lertaro의 전체 컴포넌트 버전 정보, 사용자 및 시스템 데이터 디렉토리 바로가기, 온라인 업데이트 확인 및 원클릭 무음 업데이트 기능을 제공합니다. 설정 경로는 <strong>설정 → 정보</strong>입니다.</p><h2 id="_1-컴포넌트-버전-및-프로젝트-정보" tabindex="-1">1. 컴포넌트 버전 및 프로젝트 정보 <a class="header-anchor" href="#_1-컴포넌트-버전-및-프로젝트-정보" aria-label="Permalink to “1. 컴포넌트 버전 및 프로젝트 정보”">​</a></h2><p>상단 영역에는 Lertaro 아키텍처를 구성하는 4대 핵심 컴포넌트의 버전이 표시됩니다.</p><ul><li><strong>App 버전</strong>: 전면 WPF 사용자 인터페이스 버전.</li><li><strong>Core 버전</strong>: 검색 및 인덱싱 코어 로직 라이브러리 버전.</li><li><strong>Service 버전</strong>: 백그라운드 Windows 인덱싱 서비스 버전(글자 색상으로 서비스 연결 상태 실시간 반영).</li><li><strong>CLI 버전</strong>: 명령줄 터미널 유틸리티 <code>lff</code> 버전.</li></ul><p>하단에는 공식 웹사이트, GitHub 오픈소스 리포지토리 및 온라인 문서 센터 링크가 제공됩니다.</p><h2 id="_2-데이터-디렉토리-및-5단계-백업-롤링-보관" tabindex="-1">2. 데이터 디렉토리 및 5단계 백업 롤링 보관 <a class="header-anchor" href="#_2-데이터-디렉토리-및-5단계-백업-롤링-보관" aria-label="Permalink to “2. 데이터 디렉토리 및 5단계 백업 롤링 보관”">​</a></h2><p>클릭 시 탐색기로 해당 경로를 바로 열 수 있는 두 개의 링크가 제공됩니다(폴더가 없으면 자동 생성):</p><h3 id="사용자-데이터-디렉토리-user-data-directory" tabindex="-1">사용자 데이터 디렉토리 (User Data Directory) <a class="header-anchor" href="#사용자-데이터-디렉토리-user-data-directory" aria-label="Permalink to “사용자 데이터 디렉토리 (User Data Directory)”">​</a></h3><ul><li><strong>저장 내용</strong>: 사용자 설정 파일(<code>user-settings.json</code>, <code>plugin-settings.json</code>), 검색 및 키워드 기록, 사용자 전용 캐시 및 보안 인증서.</li><li><strong>5단계 백업 롤링 보관</strong>: 설정을 저장할 때마다 기존 설정 파일이 <code>user-settings.json.bak.1</code>로 순환 백업되며 최대 <code>.bak.5</code>까지 유지됩니다. 오류나 시스템 충돌 시에도 최근 5회의 백업에서 안전하게 복원할 수 있습니다.</li></ul><h3 id="머신-데이터-디렉토리-machine-data-directory" tabindex="-1">머신 데이터 디렉토리 (Machine Data Directory) <a class="header-anchor" href="#머신-데이터-디렉토리-machine-data-directory" aria-label="Permalink to “머신 데이터 디렉토리 (Machine Data Directory)”">​</a></h3><ul><li><strong>저장 내용</strong>: 관리자 권한 서비스용 설정(<code>machine-settings.json</code>), 디스크 물리 인덱스 영구 캐시 및 백그라운드 서비스 로그.</li></ul><h3 id="저장-경로-아키텍처" tabindex="-1">저장 경로 아키텍처 <a class="header-anchor" href="#저장-경로-아키텍처" aria-label="Permalink to “저장 경로 아키텍처”">​</a></h3><ul><li><strong>설치형 버전</strong>: 사용자 데이터는 <code>%LocalAppData%\\Lertaro</code>, 머신 데이터는 <code>%ProgramData%\\Lertaro</code>에 보관.</li><li><strong>포터블 버전</strong>: 프로그램 실행 파일 옆의 <code>Data\\Users\\&lt;SID hash&gt;</code> 및 <code>Data\\Machine</code>에 보관되어 완전한 격리형 무설치 환경 지원(<a href="./../getting-started.html"><strong>포터블 데이터 격리 안내</strong></a> 참고).</li></ul><h2 id="_3-업데이트-확인-및-원클릭-업데이트" tabindex="-1">3. 업데이트 확인 및 원클릭 업데이트 <a class="header-anchor" href="#_3-업데이트-확인-및-원클릭-업데이트" aria-label="Permalink to “3. 업데이트 확인 및 원클릭 업데이트”">​</a></h2><ul><li><strong>업데이트 확인 버튼</strong>: 온라인 리포지토리에 새 버전을 질의하고 상태를 버튼에 표시(&quot;업데이트 확인 중...&quot; → &quot;최신 버전입니다&quot; 또는 새 버전 안내).</li><li><strong>새 버전 발견 시 업그레이드 방식</strong>: <ul><li><strong>무음 자동 업데이트</strong> —— 백그라운드에서 다운로드 후 덮어쓰기 업데이트를 수행하고 완료 후 자동 재시작.</li><li><strong>다운로드 페이지로 이동</strong> —— 기본 브라우저로 GitHub Releases 페이지를 열어 수동 다운로드.</li></ul></li><li><strong>권한 안내</strong>: 표준 사용자 계정에서 백그라운드 서비스를 재시작할 수 없는 경우 수동 다운로드 페이지로 안내하는 배너가 표시됩니다.</li></ul><h2 id="_4-플러그인-설정-및-설정-백업" tabindex="-1">4. 플러그인 설정 및 설정 백업 <a class="header-anchor" href="#_4-플러그인-설정-및-설정-백업" aria-label="Permalink to “4. 플러그인 설정 및 설정 백업”">​</a></h2><p>네이티브 매개변수는 <code>user-settings.json</code> 옆의 <code>plugin-settings.json</code>에 저장되며 각 파일은 최대 다섯 단계의 순환 백업을 유지합니다. 이전 내장 매개변수는 한 번만 이전합니다. 전체 설정 ZIP에는 두 파일, 캘린더 데이터, Flow 설정이 포함됩니다. 실행 가능한 Flow 플러그인 파일은 명시적으로 포함해야 합니다. 현재 플러그인 설정을 옮길 때 주 설정 파일만 복사하지 마세요.</p><p>동기화 프로그램이 백업 대상을 일시적으로 점유하면 복구 가능한 전송 오류는 현재 설정을 보존하고 앱을 정상적으로 엽니다. 실행 잠금은 포터블 설치에서도 동기화 데이터 외부인 <code>%LocalAppData%\\Lertaro\\RuntimeLocks</code>에 둡니다. 롤백을 완료하지 못하면 일부만 복원된 설정에서 플러그인을 시작하지 않습니다.</p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};